  id uuid primary key default gen_random_uuid(), league_id uuid not null, match_id uuid not null,
  official_result_id uuid not null, previous_revision_id uuid not null, draft_revision_id uuid not null,
  actor_id uuid not null, reason text not null check(length(btrim(reason))>0), created_at timestamptz not null default now(),
  unique(league_id,id), unique(official_result_id),
  foreign key(league_id,official_result_id,previous_revision_id) references public.official_match_results(league_id,id,revision_id) on delete restrict,
  foreign key(league_id,match_id,previous_revision_id) references public.match_revisions(league_id,match_id,id) on delete restrict,
  foreign key(league_id,match_id,draft_revision_id) references public.match_revisions(league_id,match_id,id) on delete restrict,
  foreign key(league_id,actor_id) references public.league_members(league_id,user_id) on delete restrict
);
