-- All functions use qualified references and a fixed search path. No caller-
-- controlled settings/flags can bypass the checks below.
-- Tighten organizer draft reads from league-wide to the assigned match.
create function ff_private.is_match_organizer(p_league uuid,p_match uuid) returns boolean
language sql stable security definer set search_path=pg_catalog,ff_private as $$
 select exists(select 1 from public.real_matches m
   join public.match_organizers o on o.league_id=m.league_id and o.user_id=m.organizer_id
   join public.league_members lm on lm.league_id=o.league_id and lm.user_id=o.user_id
   where m.league_id=p_league and m.id=p_match and m.organizer_id=auth.uid() and lm.status='active')
$$;
create or replace function ff_private.can_read_revision(p_league uuid,p_revision uuid) returns boolean
language sql stable security definer set search_path=pg_catalog,ff_private as $$
 select exists(select 1 from public.match_revisions r where r.league_id=p_league and r.id=p_revision and
   (ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,r.match_id) or (ff_private.is_member(p_league) and r.state='approved')))
$$;
create or replace function ff_private.can_read_match(p_league uuid,p_match uuid) returns boolean
language sql stable security definer set search_path=pg_catalog,ff_private as $$
 select ff_private.is_leader(p_league) or ff_private.is_match_organizer(p_league,p_match) or
   (ff_private.is_member(p_league) and exists(select 1 from public.match_revisions r where r.league_id=p_league and r.match_id=p_match and r.state='approved'))
$$;
drop policy temporary_authorizations_private on public.temporary_participant_authorizations;
create policy temporary_authorizations_private on public.temporary_participant_authorizations for select to authenticated
 using(ff_private.is_leader(league_id) or ff_private.is_match_organizer(league_id,match_id));

create function ff_private.require_organizer(p_league uuid,p_match uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  if auth.uid() is null or not exists (
    select 1 from public.real_matches m join public.match_organizers o
      on o.league_id=m.league_id and o.user_id=m.organizer_id
    join public.league_members lm on lm.league_id=o.league_id and lm.user_id=o.user_id
    where m.league_id=p_league and m.id=p_match and m.organizer_id=auth.uid() and lm.status='active'
  ) then raise exception 'not an active organizer assigned to this match' using errcode='42501'; end if;
end $$;
create function ff_private.require_leader(p_league uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
  if auth.uid() is null or not ff_private.is_leader(p_league) then
    raise exception 'not an active league leader' using errcode='42501';
  end if;
end $$;

-- Freeze match metadata after a submission; revision corrections must fork.
create function ff_private.protect_match_metadata() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if (exists(select 1 from public.match_submissions s where s.league_id=old.league_id and s.match_id=old.id)
     or exists(select 1 from public.real_match_lineups l join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id where l.league_id=old.league_id and l.match_id=old.id))
    and new is distinct from old then raise exception 'match metadata is frozen after player selection' using errcode='23514'; end if;
 return new;
end $$;
create trigger protect_match_metadata before update on public.real_matches for each row execute function ff_private.protect_match_metadata();

create function ff_private.protect_revision() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if tg_op='DELETE' then
   if exists(select 1 from public.match_submissions s where s.league_id=old.league_id and s.revision_id=old.id) then
     raise exception 'submitted revision is immutable' using errcode='23514';
   end if;
   return old;
 end if;
 if exists(select 1 from public.match_submissions s where s.league_id=old.league_id and s.revision_id=old.id) then
   if (new.id,new.league_id,new.match_id,new.version,new.match_snapshot,new.team_a_score,new.team_b_score,new.created_at,new.corrects_revision_id)
       is distinct from (old.id,old.league_id,old.match_id,old.version,old.match_snapshot,old.team_a_score,old.team_b_score,old.created_at,old.corrects_revision_id) then
     raise exception 'submitted revision is immutable' using errcode='23514';
   end if;
   if new.state is distinct from old.state and not (
       (old.state in ('draft','corrected') and new.state='submitted') or
       (old.state='submitted' and new.state in ('approved','rejected') and exists(
         select 1 from public.match_approvals a where a.league_id=old.league_id and a.revision_id=old.id and a.decision=new.state))
   ) then raise exception 'invalid revision transition' using errcode='23514'; end if;
 elsif new.state is distinct from old.state then
   raise exception 'revision state requires submission' using errcode='23514';
 end if;
 return new;
end $$;
create trigger protect_revision before update or delete on public.match_revisions for each row execute function ff_private.protect_revision();

-- Existing parent locks serialize player counts and submission against edits.
create function ff_private.guard_revision_child() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r uuid; l uuid; match_row public.real_matches%rowtype; revision_row public.match_revisions%rowtype;
  lineup_team uuid; n integer; limit_count integer;
begin
 if tg_op='DELETE' then r:=old.revision_id; l:=old.league_id; else r:=new.revision_id; l:=new.league_id; end if;
 select m.* into match_row from public.match_revisions v join public.real_matches m on m.league_id=v.league_id and m.id=v.match_id
   where v.league_id=l and v.id=r for update of m;
 if not found then raise exception 'unknown revision' using errcode='23503'; end if;
 select * into revision_row from public.match_revisions where league_id=l and id=r for update;
 if exists(select 1 from public.match_submissions s where s.league_id=l and s.revision_id=r) then
   raise exception 'submitted revision content is immutable' using errcode='23514';
 end if;
 if tg_op='UPDATE' and (old.revision_id,old.league_id) is distinct from (new.revision_id,new.league_id) then
   raise exception 'cannot move revision content' using errcode='23514'; end if;
 if tg_op='DELETE' then return old; end if;
 if tg_table_name='real_match_lineups' then
   if tg_op='UPDATE' and (new.id,new.league_id,new.match_id,new.revision_id,new.team_id) is distinct from (old.id,old.league_id,old.match_id,old.revision_id,old.team_id) then
     raise exception 'lineup identity cannot be changed' using errcode='23514'; end if;
   if new.match_id<>match_row.id or new.team_id not in (match_row.team_a_id,match_row.team_b_id) then
     raise exception 'lineup team must be a match side' using errcode='23514'; end if;
 elsif tg_table_name='real_match_lineup_players' then
   select team_id into lineup_team from public.real_match_lineups where league_id=l and revision_id=r and id=new.lineup_id;
   if not found or lineup_team not in (match_row.team_a_id,match_row.team_b_id) then
     raise exception 'invalid lineup side' using errcode='23514'; end if;
   if new.eligibility_kind='registered' and not exists(
     select 1 from public.real_team_players p where p.league_id=l and p.team_id=lineup_team and p.player_id=new.player_id
       and p.valid_from<=match_row.starts_at and (p.valid_until is null or p.valid_until>match_row.starts_at)
   ) then raise exception 'player not registered for match side at kickoff' using errcode='23514'; end if;
   if new.eligibility_kind='temporary' and not exists(
     select 1 from public.temporary_participant_authorizations a where a.league_id=l and a.match_id=match_row.id
       and a.team_id=lineup_team and a.player_id=new.player_id
   ) then raise exception 'missing temporary authorization' using errcode='23514'; end if;
   limit_count:=case new.selection when 'starter' then match_row.starters_per_side else match_row.max_substitutes end;
   select count(*) into n from public.real_match_lineup_players p where p.league_id=l and p.lineup_id=new.lineup_id
     and p.selection=new.selection and (tg_op<>'UPDATE' or p.id<>old.id);
   if n>=limit_count then raise exception 'lineup exceeds format limit' using errcode='23514'; end if;
 end if;
 return new;
end $$;
create trigger guard_real_lineup before insert or update or delete on public.real_match_lineups for each row execute function ff_private.guard_revision_child();
create trigger guard_real_players before insert or update or delete on public.real_match_lineup_players for each row execute function ff_private.guard_revision_child();
create trigger guard_match_events before insert or update or delete on public.match_events for each row execute function ff_private.guard_revision_child();

-- Prevent a registration used by any selected lineup from being rewritten.
-- Lock every related match before testing submissions, matching lineup writes.
create function ff_private.guard_roster_history() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 perform m.id from public.real_matches m join public.real_match_lineups l on l.league_id=m.league_id and l.match_id=m.id
 join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id
 where m.league_id=old.league_id and l.team_id=old.team_id and p.player_id=old.player_id and p.eligibility_kind='registered'
   and old.valid_from<=m.starts_at and (old.valid_until is null or old.valid_until>m.starts_at)
 order by m.id for update of m;
 if exists(select 1 from public.real_matches m join public.real_match_lineups l on l.league_id=m.league_id and l.match_id=m.id
   join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id
   where m.league_id=old.league_id and l.team_id=old.team_id and p.player_id=old.player_id and p.eligibility_kind='registered'
   and old.valid_from<=m.starts_at and (old.valid_until is null or old.valid_until>m.starts_at)) then
   raise exception 'selected lineup references registration' using errcode='23514'; end if;
 if tg_op='DELETE' then return old; end if; return new;
end $$;
create trigger guard_roster_history before update or delete on public.real_team_players for each row execute function ff_private.guard_roster_history();

create function ff_private.guard_temp_authorization() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare m public.real_matches%rowtype;
begin
 if tg_op<>'INSERT' then raise exception 'authorization is append-only' using errcode='23514'; end if;
 perform ff_private.require_leader(new.league_id);
 if new.authorized_by is distinct from auth.uid() then raise exception 'invalid authorizer' using errcode='42501'; end if;
 select * into m from public.real_matches where league_id=new.league_id and id=new.match_id for update;
 if not found or new.team_id not in (m.team_a_id,m.team_b_id) then raise exception 'authorization must target a match side' using errcode='23514'; end if;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data,reason)
 values(new.league_id,auth.uid(),'authorize_temporary_participant','match',new.match_id,to_jsonb(new),new.reason);
 return new;
end $$;
create trigger guard_temp_auth before insert or update or delete on public.temporary_participant_authorizations for each row execute function ff_private.guard_temp_authorization();

