create function ff_private.validate_lineups(p_league uuid,p_revision uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare m public.real_matches%rowtype; actual integer; sides integer;
begin
 select m0.* into m from public.match_revisions r join public.real_matches m0 on m0.league_id=r.league_id and m0.id=r.match_id
 where r.league_id=p_league and r.id=p_revision for update of m0;
 if not found then raise exception 'revision not found' using errcode='23503'; end if;
 select count(*) into sides from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision
   and l.team_id in (m.team_a_id,m.team_b_id);
 if sides<>2 then raise exception 'both match sides required' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision and
    (select count(*) from public.real_match_lineup_players p where p.lineup_id=l.id and p.selection='starter')<>m.starters_per_side)
 then raise exception 'each side needs expected starters' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineups l where l.league_id=p_league and l.revision_id=p_revision and
    (select count(*) from public.real_match_lineup_players p where p.lineup_id=l.id and p.selection='substitute')>m.max_substitutes)
 then raise exception 'too many substitutes' using errcode='23514'; end if;
 if exists(select 1 from public.real_match_lineup_players p join public.real_match_lineups l on l.league_id=p.league_id and l.id=p.lineup_id
   where p.league_id=p_league and p.revision_id=p_revision and
   ((p.eligibility_kind='registered' and not exists(select 1 from public.real_team_players rp where rp.league_id=p.league_id and rp.team_id=l.team_id and rp.player_id=p.player_id and rp.valid_from<=m.starts_at and (rp.valid_until is null or rp.valid_until>m.starts_at)))
   or (p.eligibility_kind='temporary' and not exists(select 1 from public.temporary_participant_authorizations a where a.league_id=p.league_id and a.match_id=m.id and a.team_id=l.team_id and a.player_id=p.player_id))))
 then raise exception 'ineligible player' using errcode='23514'; end if;
end $$;

-- After a correction has opened, only its newly approved lineup may back a
-- result; older approvals cannot silently bypass correction reapproval.
create function ff_private.require_latest_corrected_lineup(p_league uuid,p_match uuid,p_revision uuid) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare required_revision uuid;
begin
 select c.draft_revision_id into required_revision from public.match_corrections c
 join public.match_revisions r on r.league_id=c.league_id and r.id=c.draft_revision_id
 where c.league_id=p_league and c.match_id=p_match order by r.version desc limit 1;
 if required_revision is not null and required_revision<>p_revision then
   raise exception 'latest corrected lineup requires reapproval' using errcode='23514'; end if;
end $$;

create function ff_private.validate_submission() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare rev public.match_revisions%rowtype; source_revision uuid;
begin
 perform ff_private.require_organizer(new.league_id,new.match_id);
 if new.submitted_by is distinct from auth.uid() then raise exception 'invalid submitter' using errcode='42501'; end if;
 perform 1 from public.real_matches where league_id=new.league_id and id=new.match_id for update;
 select * into rev from public.match_revisions where league_id=new.league_id and match_id=new.match_id and id=new.revision_id for update;
 if not found or rev.state not in ('draft','corrected') or exists(select 1 from public.match_submissions s where s.league_id=new.league_id and s.revision_id=new.revision_id) then
   raise exception 'revision is not an unsubmitted draft' using errcode='23514'; end if;
 perform ff_private.validate_lineups(new.league_id,new.revision_id);
 if new.kind='result' then
   if rev.team_a_score is null or rev.team_b_score is null then raise exception 'result needs both scores' using errcode='23514'; end if;
   select a.revision_id into source_revision from public.match_approvals a
    where a.league_id=new.league_id and a.match_id=new.match_id and a.id=new.approved_lineup_approval_id and a.kind='lineup' and a.decision='approved';
   if source_revision is null then raise exception 'approved lineup required' using errcode='23514'; end if;
   perform ff_private.require_latest_corrected_lineup(new.league_id,new.match_id,source_revision);
   if exists(
     (select l.team_id,p.player_id,p.selection,p.actual_position,p.eligibility_kind,p.eligibility_evidence from public.real_match_lineups l join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id where l.league_id=new.league_id and l.revision_id=source_revision
      except select l.team_id,p.player_id,p.selection,p.actual_position,p.eligibility_kind,p.eligibility_evidence from public.real_match_lineups l join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id where l.league_id=new.league_id and l.revision_id=new.revision_id)
      union all
     (select l.team_id,p.player_id,p.selection,p.actual_position,p.eligibility_kind,p.eligibility_evidence from public.real_match_lineups l join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id where l.league_id=new.league_id and l.revision_id=new.revision_id
      except select l.team_id,p.player_id,p.selection,p.actual_position,p.eligibility_kind,p.eligibility_evidence from public.real_match_lineups l join public.real_match_lineup_players p on p.league_id=l.league_id and p.lineup_id=l.id where l.league_id=new.league_id and l.revision_id=source_revision)
   ) then raise exception 'result lineup differs from approved lineup' using errcode='23514'; end if;
   if rev.match_snapshot is distinct from (select match_snapshot from public.match_revisions where league_id=new.league_id and id=source_revision) then
     raise exception 'result metadata differs from approved lineup' using errcode='23514'; end if;
 end if;
 return new;
end $$;
create trigger validate_submission before insert on public.match_submissions for each row execute function ff_private.validate_submission();
create function ff_private.after_submission() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 update public.match_revisions set state='submitted' where league_id=new.league_id and id=new.revision_id;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data) values(new.league_id,auth.uid(),'submit_'||new.kind,'match',new.match_id,to_jsonb(new));
 return new;
end $$;
create trigger after_submission after insert on public.match_submissions for each row execute function ff_private.after_submission();

create function ff_private.validate_approval() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare sub public.match_submissions%rowtype;
begin
 perform ff_private.require_leader(new.league_id);
 if new.reviewed_by is distinct from auth.uid() then raise exception 'invalid reviewer' using errcode='42501'; end if;
 perform 1 from public.real_matches where league_id=new.league_id and id=new.match_id for update;
 select * into sub from public.match_submissions where league_id=new.league_id and id=new.submission_id and match_id=new.match_id and revision_id=new.revision_id and kind=new.kind;
 if not found or not exists(select 1 from public.match_revisions where league_id=new.league_id and id=new.revision_id and state='submitted') then
   raise exception 'submission is not awaiting review' using errcode='23514'; end if;
 if sub.submitted_by=auth.uid() then raise exception 'self approval is forbidden' using errcode='42501'; end if;
 if new.decision='rejected' and (new.reason is null or length(btrim(new.reason))=0) then raise exception 'rejection needs a reason' using errcode='23514'; end if;
 return new;
end $$;
create trigger validate_approval before insert on public.match_approvals for each row execute function ff_private.validate_approval();
create function ff_private.after_approval() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 update public.match_revisions set state=new.decision where league_id=new.league_id and id=new.revision_id;
 if new.kind='result' and new.decision='approved' then
   insert into public.official_match_results(league_id,match_id,revision_id,approval_id) values(new.league_id,new.match_id,new.revision_id,new.id);
 end if;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data,reason)
 values(new.league_id,auth.uid(),'review_'||new.kind,'match',new.match_id,to_jsonb(new),new.reason);
 return new;
end $$;
create trigger after_approval after insert on public.match_approvals for each row execute function ff_private.after_approval();

