create trigger revision_insert_guard before insert on public.match_revisions for each row execute function ff_private.revision_insert_guard();

-- Versioned scoring policy cannot change after publication. Publishing is a
-- separate privileged future workflow; there are no default rule values.
create function ff_private.guard_rules() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare l uuid; r uuid; current_state text;
begin
 if tg_table_name='scoring_rule_values' then
   if tg_op='DELETE' then l:=old.league_id; r:=old.rule_set_id; else l:=new.league_id; r:=new.rule_set_id; end if;
   if tg_op='UPDATE' and (old.league_id,old.rule_set_id) is distinct from (new.league_id,new.rule_set_id) then raise exception 'cannot move rule value' using errcode='23514'; end if;
   select state into current_state from public.scoring_rule_sets where league_id=l and id=r for update;
   if current_state is distinct from 'draft' then raise exception 'published rules are immutable' using errcode='23514'; end if;
   if tg_op='DELETE' then return old; else return new; end if;
 end if;
 if old.state<>'draft' then raise exception 'published rules are immutable' using errcode='23514'; end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end $$;
create trigger guard_rule_set before update or delete on public.scoring_rule_sets for each row execute function ff_private.guard_rules();
create trigger guard_rule_value before insert or update or delete on public.scoring_rule_values for each row execute function ff_private.guard_rules();

create function ff_private.guard_official_result() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if tg_op='DELETE' then raise exception 'official result is historical' using errcode='23514'; end if;
 if tg_op='INSERT' then
   if not new.is_current or not exists(select 1 from public.match_approvals a join public.match_revisions r on r.league_id=a.league_id and r.id=a.revision_id
     where a.league_id=new.league_id and a.match_id=new.match_id and a.revision_id=new.revision_id and a.id=new.approval_id and a.kind='result' and a.decision='approved' and r.state='approved') then
     raise exception 'official result requires approved result revision' using errcode='23514'; end if;
   return new;
 end if;
 perform ff_private.require_leader(old.league_id);
 if not exists(select 1 from public.match_corrections c where c.league_id=old.league_id and c.official_result_id=old.id and c.actor_id=auth.uid()) then
   raise exception 'correction record required to supersede result' using errcode='23514'; end if;
 if not old.is_current or new.is_current or (new.id,new.league_id,new.match_id,new.revision_id,new.approval_id,new.decision,new.kind)
    is distinct from (old.id,old.league_id,old.match_id,old.revision_id,old.approval_id,old.decision,old.kind) then
   raise exception 'official result may only be superseded' using errcode='23514'; end if;
 return new;
end $$;
create trigger guard_official_result before insert or update or delete on public.official_match_results for each row execute function ff_private.guard_official_result();

create function ff_private.guard_run() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if tg_op='DELETE' then raise exception 'scoring run is historical' using errcode='23514'; end if;
 if tg_op='INSERT' then
   if new.status<>'pending' or new.sources_sealed or not exists(select 1 from public.scoring_rule_sets r join public.gameweeks g on g.league_id=r.league_id and g.scoring_rule_set_id=r.id
       where r.league_id=new.league_id and r.id=new.rule_set_id and r.state='published' and g.id=new.gameweek_id) then
     raise exception 'run requires pinned published rules and pending status' using errcode='23514'; end if;
   return new;
 end if;
 perform ff_private.require_leader(old.league_id);
 if (new.id,new.league_id,new.gameweek_id,new.rule_set_id,new.input_hash,new.created_at) is distinct from
    (old.id,old.league_id,old.gameweek_id,old.rule_set_id,old.input_hash,old.created_at) then raise exception 'run identity is immutable' using errcode='23514'; end if;
 if old.status='pending' and new.status='pending' and not old.sources_sealed and new.sources_sealed then
   if not exists(select 1 from public.scoring_run_sources s where s.league_id=old.league_id and s.scoring_run_id=old.id) then raise exception 'cannot seal empty source set' using errcode='23514'; end if;
   return new;
 end if;
 if old.status not in ('pending','complete') or new.status<>'superseded' or old.sources_sealed is distinct from new.sources_sealed then
   raise exception 'run can only be sealed or superseded' using errcode='23514'; end if;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,before_data,after_data)
 values(old.league_id,auth.uid(),'supersede_scoring','scoring_run',old.id,to_jsonb(old),to_jsonb(new));
 return new;
end $$;
create trigger guard_run before insert or update or delete on public.scoring_runs for each row execute function ff_private.guard_run();

create function ff_private.guard_run_source() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if tg_op<>'INSERT' then raise exception 'run sources are immutable' using errcode='23514'; end if;
 -- Serialize validation against result corrections on the source match.
 perform m.id from public.official_match_results o join public.real_matches m on m.league_id=o.league_id and m.id=o.match_id
 where o.league_id=new.league_id and o.id=new.official_result_id for update of m;
 if not exists(select 1 from public.scoring_runs r
   join public.official_match_results o on o.league_id=r.league_id
   join public.real_matches m on m.league_id=o.league_id and m.id=o.match_id
   join public.match_approvals a on a.league_id=o.league_id and a.id=o.approval_id and a.revision_id=o.revision_id
   join public.match_revisions v on v.league_id=o.league_id and v.id=o.revision_id
   where r.league_id=new.league_id and r.id=new.scoring_run_id and r.status='pending' and not r.sources_sealed
     and o.id=new.official_result_id and o.revision_id=new.revision_id and o.is_current
     and m.gameweek_id=r.gameweek_id and a.kind='result' and a.decision='approved' and v.state='approved') then
   raise exception 'run source must be current approved result in same gameweek' using errcode='23514'; end if;
 return new;
end $$;
create trigger guard_run_source before insert or update or delete on public.scoring_run_sources for each row execute function ff_private.guard_run_source();
create function ff_private.require_run_source() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if not exists(select 1 from public.scoring_runs r where r.league_id=new.league_id and r.id=new.id and r.sources_sealed) or not exists(select 1 from public.scoring_run_sources s where s.league_id=new.league_id and s.scoring_run_id=new.id) then
   raise exception 'every scoring run requires an approved source' using errcode='23514'; end if;
 return null;
end $$;
create constraint trigger require_run_source after insert on public.scoring_runs deferrable initially deferred for each row execute function ff_private.require_run_source();

-- No scoring algorithm is approved yet: even a privileged workflow cannot
-- insert arbitrary performance/score rows or publish a completed run. This is
-- deliberately stricter than the future requirements and is not a scorer.
create function ff_private.block_unimplemented_scoring() returns trigger
language plpgsql set search_path=pg_catalog,ff_private as $$
begin raise exception 'scoring calculation not implemented; writes blocked' using errcode='42501'; end $$;
create trigger block_performance before insert or update or delete on public.match_player_performances for each row execute function ff_private.block_unimplemented_scoring();
create trigger block_score_item before insert or update or delete on public.fantasy_score_items for each row execute function ff_private.block_unimplemented_scoring();
create trigger block_fantasy_score before insert or update or delete on public.fantasy_scores for each row execute function ff_private.block_unimplemented_scoring();
-- Standings are scores too: block fabricated projections; only stale marking of
-- existing rows during an authorized correction is permitted.
create function ff_private.guard_standings() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 if tg_op<>'UPDATE' then raise exception 'standings calculation not implemented; writes blocked' using errcode='42501'; end if;
 perform ff_private.require_leader(old.league_id);
 if new is not distinct from old then return new; end if;
 if new.is_stale is not true or (new.league_id,new.season_id,new.fantasy_team_id,new.mode,new.fantasy_points,new.h2h_points,new.computed_at)
   is distinct from (old.league_id,old.season_id,old.fantasy_team_id,old.mode,old.fantasy_points,old.h2h_points,old.computed_at) then
   raise exception 'only standings invalidation is permitted' using errcode='42501'; end if;
 return new;
end $$;
create trigger guard_standings before insert or update or delete on public.league_standings for each row execute function ff_private.guard_standings();


-- Draft prototypes. No authenticated/anon EXECUTE grants in this offline
-- migration. A mock test gateway may grant only these signatures in tests.
create function ff_private.submit_lineup(p_league uuid,p_revision uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare match_id uuid; submission_id uuid;
begin
 select r.match_id into match_id from public.match_revisions r where r.league_id=p_league and r.id=p_revision;
 perform ff_private.require_organizer(p_league,match_id);
 insert into public.match_submissions(league_id,match_id,revision_id,kind,submitted_by)
 values(p_league,match_id,p_revision,'lineup',auth.uid()) returning id into submission_id;
 return submission_id;
end $$;
-- Forking copies the reviewed lineup into a fresh, editable result revision.
-- Event/score semantics remain product-configurable, validated only structurally.
create function ff_private.fork_result(p_league uuid,p_lineup_approval uuid) returns uuid
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare a public.match_approvals%rowtype; next_rev uuid; next_ver integer; line record; next_line uuid;
begin
 select * into a from public.match_approvals where league_id=p_league and id=p_lineup_approval and kind='lineup' and decision='approved';
 if not found then raise exception 'approved lineup required' using errcode='23514'; end if;
 perform ff_private.require_organizer(p_league,a.match_id);
 perform 1 from public.real_matches where league_id=p_league and id=a.match_id for update;
 perform ff_private.require_latest_corrected_lineup(p_league,a.match_id,a.revision_id);
 select coalesce(max(version),0)+1 into next_ver from public.match_revisions where league_id=p_league and match_id=a.match_id;
 insert into public.match_revisions(league_id,match_id,version,match_snapshot)
 select p_league,a.match_id,next_ver,match_snapshot from public.match_revisions where league_id=p_league and id=a.revision_id returning id into next_rev;
 for line in select * from public.real_match_lineups where league_id=p_league and revision_id=a.revision_id loop
   insert into public.real_match_lineups(league_id,match_id,revision_id,team_id) values(p_league,a.match_id,next_rev,line.team_id) returning id into next_line;
   insert into public.real_match_lineup_players(league_id,revision_id,lineup_id,player_id,selection,actual_position,eligibility_kind,eligibility_evidence)
   select league_id,next_rev,next_line,player_id,selection,actual_position,eligibility_kind,eligibility_evidence from public.real_match_lineup_players where league_id=p_league and lineup_id=line.id;
 end loop;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data) values(p_league,auth.uid(),'fork_result','match',a.match_id,jsonb_build_object('lineup_approval',a.id,'draft_revision',next_rev));
 return next_rev;
end $$;
create function ff_private.set_result_score(p_league uuid,p_revision uuid,p_score_a integer,p_score_b integer) returns void
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare m uuid;
begin
 select match_id into m from public.match_revisions where league_id=p_league and id=p_revision;
 perform ff_private.require_organizer(p_league,m);
 perform 1 from public.real_matches where league_id=p_league and id=m for update;
 update public.match_revisions set team_a_score=p_score_a,team_b_score=p_score_b where league_id=p_league and id=p_revision;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data) values(p_league,auth.uid(),'draft_result_score','match',m,jsonb_build_object('revision',p_revision,'team_a_score',p_score_a,'team_b_score',p_score_b));
end $$;
