-- Only a leader can begin an approved-result correction. Old result and all
-- dependent pending runs are superseded atomically; historic rows are retained.
create function ff_private.validate_correction() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
begin
 perform ff_private.require_leader(new.league_id);
 if new.actor_id is distinct from auth.uid() then raise exception 'invalid correction actor' using errcode='42501'; end if;
 perform 1 from public.real_matches where league_id=new.league_id and id=new.match_id for update;
 if not exists(select 1 from public.official_match_results o join public.match_revisions v on v.league_id=o.league_id and v.match_id=o.match_id and v.id=new.draft_revision_id
   where o.league_id=new.league_id and o.match_id=new.match_id and o.id=new.official_result_id and o.revision_id=new.previous_revision_id and o.is_current
   and v.corrects_revision_id=o.revision_id and v.state='draft') then raise exception 'correction requires a new draft of the current result' using errcode='23514'; end if;
 return new;
end $$;
create trigger validate_correction before insert on public.match_corrections for each row execute function ff_private.validate_correction();
create trigger correction_append_only before update or delete on public.match_corrections for each row execute function ff_private.append_only();
create function ff_private.after_correction() returns trigger
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare affected uuid[];
begin
 select coalesce(array_agg(distinct r.id),'{}'::uuid[]) into affected from public.scoring_runs r join public.scoring_run_sources s on s.league_id=r.league_id and s.scoring_run_id=r.id
 where s.league_id=new.league_id and s.official_result_id=new.official_result_id and r.status in ('pending','complete');
 update public.official_match_results set is_current=false where id=new.official_result_id and league_id=new.league_id;
 update public.scoring_runs set status='superseded' where league_id=new.league_id and id=any(affected);
 update public.league_standings set is_stale=true where league_id=new.league_id and season_id=(select g.season_id from public.real_matches m join public.gameweeks g on g.league_id=m.league_id and g.id=m.gameweek_id where m.league_id=new.league_id and m.id=new.match_id);
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,reason,before_data,after_data)
 values(new.league_id,auth.uid(),'open_correction','match',new.match_id,new.reason,jsonb_build_object('official_result',new.official_result_id,'revision',new.previous_revision_id),jsonb_build_object('correction',new.id,'draft_revision',new.draft_revision_id,'superseded_runs',affected));
 return new;
end $$;
create trigger after_correction after insert on public.match_corrections for each row execute function ff_private.after_correction();

create function ff_private.open_correction(p_league uuid,p_match uuid,p_reason text) returns uuid
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare official public.official_match_results%rowtype; next_rev uuid; next_ver integer; old_lineup record; next_lineup uuid;
begin
 perform ff_private.require_leader(p_league);
 if p_reason is null or length(btrim(p_reason))=0 then raise exception 'correction requires a reason' using errcode='23514'; end if;
 perform 1 from public.real_matches where league_id=p_league and id=p_match for update;
 select * into official from public.official_match_results where league_id=p_league and match_id=p_match and is_current for update;
 if not found then raise exception 'current approved result required' using errcode='23514'; end if;
 select coalesce(max(version),0)+1 into next_ver from public.match_revisions where league_id=p_league and match_id=p_match;
 insert into public.match_revisions(league_id,match_id,version,match_snapshot,corrects_revision_id)
 select p_league,p_match,next_ver,match_snapshot,id from public.match_revisions where league_id=p_league and id=official.revision_id returning id into next_rev;
 for old_lineup in select * from public.real_match_lineups where league_id=p_league and revision_id=official.revision_id loop
   insert into public.real_match_lineups(league_id,match_id,revision_id,team_id) values(p_league,p_match,next_rev,old_lineup.team_id) returning id into next_lineup;
   insert into public.real_match_lineup_players(league_id,revision_id,lineup_id,player_id,selection,actual_position,eligibility_kind,eligibility_evidence)
   select league_id,next_rev,next_lineup,player_id,selection,actual_position,eligibility_kind,eligibility_evidence from public.real_match_lineup_players where league_id=p_league and lineup_id=old_lineup.id;
 end loop;
 insert into public.match_corrections(league_id,match_id,official_result_id,previous_revision_id,draft_revision_id,actor_id,reason)
 values(p_league,p_match,official.id,official.revision_id,next_rev,auth.uid(),p_reason);
 return next_rev;
end $$;

-- Create/retry a pending run with an exact canonical source set. No points are
-- created. Locking serializes retries against correction and gameweek changes.
create function ff_private.start_scoring(p_league uuid,p_gameweek uuid,p_sources uuid[]) returns uuid
language plpgsql security definer set search_path=pg_catalog,ff_private as $$
declare r uuid; key_text text; hash_value text; rule_id uuid; cnt integer; expected integer; existing_ids uuid[]; requested_ids uuid[];
begin
 perform ff_private.require_leader(p_league);
 if p_sources is null or cardinality(p_sources)=0 or array_position(p_sources,null) is not null then raise exception 'approved sources required' using errcode='23514'; end if;
 select count(*),count(distinct x),array_agg(x order by x),string_agg(x::text,',' order by x) into cnt,expected,requested_ids,key_text from unnest(p_sources) x;
 if cnt<>expected then raise exception 'duplicate source' using errcode='23514'; end if;
 select scoring_rule_set_id into rule_id from public.gameweeks where league_id=p_league and id=p_gameweek for update;
 if rule_id is null then raise exception 'pinned rules required' using errcode='23514'; end if;
 -- Lock matches first in deterministic order before checking current pointers.
 perform 1 from public.real_matches m where m.league_id=p_league and m.gameweek_id=p_gameweek order by m.id for update;
 select count(*) into cnt from public.official_match_results o join public.real_matches m on m.league_id=o.league_id and m.id=o.match_id
 join public.match_approvals a on a.league_id=o.league_id and a.id=o.approval_id and a.revision_id=o.revision_id
 join public.match_revisions v on v.league_id=o.league_id and v.id=o.revision_id
 where o.league_id=p_league and m.gameweek_id=p_gameweek and o.id=any(p_sources) and o.is_current and a.kind='result' and a.decision='approved' and v.state='approved';
 if cnt<>expected then raise exception 'all sources must be current approved results' using errcode='23514'; end if;
 hash_value:=md5(rule_id::text||':'||key_text);
 select id into r from public.scoring_runs where league_id=p_league and gameweek_id=p_gameweek and input_hash=hash_value;
 if r is not null then
   select array_agg(official_result_id order by official_result_id) into existing_ids from public.scoring_run_sources where league_id=p_league and scoring_run_id=r;
   if existing_ids is distinct from requested_ids or not exists(select 1 from public.scoring_runs where league_id=p_league and id=r and rule_set_id=rule_id and status='pending') then
     raise exception 'run key conflict or superseded run' using errcode='23514'; end if;
   return r;
 end if;
 insert into public.scoring_runs(league_id,gameweek_id,rule_set_id,status,input_hash) values(p_league,p_gameweek,rule_id,'pending',hash_value) returning id into r;
 insert into public.scoring_run_sources(league_id,scoring_run_id,official_result_id,revision_id)
 select p_league,r,o.id,o.revision_id from public.official_match_results o where o.league_id=p_league and o.id=any(p_sources);
 update public.scoring_runs set sources_sealed=true where league_id=p_league and id=r;
 insert into public.audit_logs(league_id,actor_id,action,entity_type,entity_id,after_data)
 values(p_league,auth.uid(),'start_scoring','scoring_run',r,jsonb_build_object('rule_set',rule_id,'sources',requested_ids));
 return r;
end $$;

revoke all on all functions in schema ff_private from public, anon, authenticated;
-- Restore only the original read-policy helper grants; no workflow is exposed.
grant execute on function ff_private.is_member(uuid),ff_private.is_leader(uuid),ff_private.is_organizer(uuid),ff_private.owns_team(uuid,uuid),
 ff_private.can_read_lineup(uuid,uuid),ff_private.can_read_revision(uuid,uuid),ff_private.can_read_match(uuid,uuid),
 ff_private.can_read_suggestion(uuid,uuid),ff_private.can_read_image(text),ff_private.is_match_organizer(uuid,uuid) to authenticated;
